import {icon} from './content.js';
import {createSystemsScene} from './systems-scene.js';
import {desktopConnections,serverConnections,deskSteps,serverSteps,createDesktop,createServer,desktopStatus,serverStatus,desktopAction,serverAction,toggleConnection,validateConfig,runCommand,reconcileServer,event} from './systems-model.js';
const $=s=>document.querySelector(s),escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let desktop=createDesktop(),server=createServer(),course='desktop',scene=null,flowTimer,installTimer,wizardPage=0,config=null;const history=[];
const state=()=>course==='server'?server:desktop,steps=()=>course==='server'?serverSteps:deskSteps;
const details={pc:['데스크톱 PC','전원 버튼으로 부팅하고 USB 입력을 처리합니다. HDMI는 출력, Ethernet은 양방향 통신을 담당합니다.'],monitor:['모니터','전원과 영상 케이블이 모두 필요합니다. HDMI를 분리하면 PC는 계속 동작하지만 화면이 나오지 않아요.'],keyboard:['키보드','USB 입력 장치입니다. 케이블을 분리하면 새로운 키 입력을 보내지 못하지만 이미 입력한 내용은 PC에 남아 있습니다.'],mouse:['마우스','이동·버튼 입력을 PC로 보냅니다. PC가 입력을 처리해 화면을 갱신하므로 입력 케이블과 영상 케이블이 모두 관여합니다.'],router:['라우터 / 게이트웨이','서로 다른 IP 네트워크 사이의 패킷을 전달합니다. 이 실습 장비는 DNS 역할도 함께 맡습니다. 같은 VLAN 안의 통신은 스위치에서 처리돼요.'],strip:['멀티탭','PC와 모니터에 전원을 공급합니다. 전원 연결과 데이터 연결은 서로 다른 경로예요.'],server:['2U 랙 서버','높이 2U인 서버에 CPU·메모리·SSD와 두 전원 모듈을 넣은 개념 모델입니다. 랙 고정·전원·네트워크·운영체제가 모두 준비되어야 서비스를 제공할 수 있어요.'],rack:['12U 랙','여러 장비를 규격에 맞게 장착하는 구조물입니다. 케이블 정리, 전력 용량, 무게, 냉각, 접지까지 실제 설치 계획에 포함합니다.'],disks:['SSD 480 GB × 2','가상 설치 화면에서 단일 디스크나 RAID 1 개념 구성을 선택합니다. RAID 1의 가용 용량은 한 디스크 분량이며, 백업은 별도로 필요합니다.'],switch:['L2 스위치','같은 LAN/VLAN에 속한 장치의 이더넷 프레임을 전달합니다. 관리 PC와 서버가 같은 서브넷이면 라우터 업링크가 끊겨도 직접 IP로 통신할 수 있어요.'],ups:['UPS','정전 때 배터리 전력을 제공합니다. 실습에서는 남은 시간을 15초로 압축했습니다. 배터리가 끝나면 전원이 끊기며, 전력 복구 후 서버를 다시 켜야 해요.'],pdu:['PDU','UPS의 전력을 랙 장비에 나눠 줍니다. 두 PSU가 같은 PDU에 연결된 이 실습은 PSU 고장에는 대응하지만 PDU 장애에는 대응하지 못합니다.'],client:['관리 PC','10.20.0.100의 관리자 컴퓨터입니다. SSH로 서버에 원격 접속하거나 HTTP로 웹 페이지를 요청합니다. 서버와 다른 컴퓨터라는 점을 기억하세요.'],console:['로컬 KVM 콘솔','Keyboard · Video · Mouse 연결입니다. 네트워크가 끊기거나 SSH 설정이 잘못돼도 서버를 직접 관리할 수 있어요.'],consoleKeyboard:['콘솔 키보드','KVM을 통해 서버의 로컬 터미널로 입력합니다. 관리 PC의 SSH 세션과는 독립적입니다.'],media:['설치 USB','Ubuntu Server 설치 프로그램을 담은 가상 부팅 미디어입니다. 설치가 끝나면 제거하고 디스크에서 재부팅합니다.'],mains:['시설 전원','전원 경로의 출발점입니다. 시설 전원을 분리하면 UPS가 제한된 시간 동안 랙을 유지합니다.']};
const terminalHTML=`<div class="panel-card"><div class="panel-heading"><div><div class="overline">TRY THE COMMANDS</div><h3>실습 터미널</h3></div><span>브라우저 안의 가상 명령</span></div><div class="terminal-tabs"><button data-session="local" class="active">서버 로컬 콘솔</button><button data-session="client">관리 PC / SSH</button></div><div class="terminal"><div class="terminal-output" id="terminal-output" role="log" aria-label="가상 터미널 출력" aria-live="polite"></div><form class="terminal-form" id="terminal-form"><label class="terminal-prompt" for="terminal-input" id="terminal-prompt">admin@office-web:~$</label><input class="terminal-input" id="terminal-input" aria-label="가상 Linux 명령" placeholder="help" autocomplete="off" spellcheck="false"><button type="submit">실행</button></form><div class="terminal-shortcuts"><button data-command="help">help</button><button data-command="ip addr">ip addr</button><button data-command="ping office.example">ping</button><button data-command="systemctl status nginx">nginx 상태</button><button data-command="curl http://office.example">curl</button><button data-command="sudo ufw status">UFW</button></div><div class="terminal-sim-note">명령·파일·패킷은 모두 모의 데이터입니다. 실제 OS 설치나 외부 서버 접속은 하지 않습니다.</div></div></div>`;
const desktopHTML=`<div class="panel-card"><div class="panel-heading"><div><div class="overline">INPUT → PROCESS → OUTPUT</div><h3>직접 입력해 보세요</h3></div><span id="io-status">연결 대기</span></div><div class="io-monitor off" id="io-monitor"><div class="screen-caption" id="io-screen-caption">MONITOR / POWER OFF</div><div class="io-screen-output" id="io-screen-output">전원과 HDMI를 연결하세요.</div><div class="io-click-output" id="io-click-output"></div></div><div class="io-controls"><form class="io-input-row" id="io-form"><input id="io-input" aria-label="가상 키보드 입력" placeholder="화면에 표시할 문장 입력" maxlength="80" autocomplete="off"><button class="secondary-button" type="submit">키 입력 전송</button></form><div class="io-buttons"><button class="secondary-button" id="io-click">${icon('mouse')} 마우스 클릭</button><button class="secondary-button" id="desk-power">${icon('power')} PC 전원</button><button class="secondary-button" id="desk-ping">${icon('cable')} ping 테스트</button></div></div><pre class="network-console" id="desk-network">PC → 라우터\n전원과 LAN을 연결한 뒤 ping을 보내보세요.</pre></div>`;
function frame(){const srv=course==='server';$('#system-lab').innerHTML=`<div class="system-shell"><aside class="system-sidebar"><div class="overline">${srv?'OFFICE INFRASTRUCTURE':'YOUR PERSONAL WORKSPACE'}</div><h2>${srv?'처음부터, 서버 한 대':'연결하면, 시작되는 것'}</h2><p>${srv?'장비 설치부터 Linux와 웹 서비스까지.':'전원, 신호, 입력과 출력의 관계를 배워요.'}</p><div class="progress-caption"><span>완료한 단계</span><span id="system-progress"></span></div><div class="progress-track"><div id="system-progress-fill"></div></div><ol class="systems-steps" id="systems-steps" aria-label="${srv?'서버 구축':'데스크 셋업'} 단계"></ol><button class="secondary-button" id="system-reset">${icon('rotate')} 이 실습 초기화</button><div class="sim-only"><strong>LEARNING SIMULATION</strong><br>${srv?'Ubuntu Server 24.04 LTS 기반의 개념 모델입니다. 가상 디스크와 가상 네트워크만 사용해요.':'장치를 연결하거나 분리해 결과를 비교하세요. 전원과 데이터가 흐르는 길은 다릅니다.'}</div></aside><div class="system-main"><div class="system-status" id="system-status"></div><div class="system-stage" id="system-stage"><div class="system-canvas" id="system-canvas"></div><div class="stage-heading">${srv?'RACK 01 · OFFICE LAB':'DESK 01 · PERSONAL LAB'}<small>${srv?'2U SERVER / 2× SSD / 32 GB RAM':'ATX PC / HDMI MONITOR / USB / ETHERNET'}</small></div><div class="view-tools"><button class="icon-button" id="system-camera" aria-label="실험실 시점 초기화" title="시점 초기화">${icon('rotate')}</button><button class="icon-button" id="system-rear" aria-label="실험실 뒷면 보기" title="뒷면 보기">${icon('box')}</button><button class="icon-button" id="system-fullscreen" aria-label="실험실 전체 화면" title="전체 화면">${icon('expand')}</button></div><div class="stage-legend"><span><i class="legend-dot power-color"></i>전원</span><span><i class="legend-dot network-color"></i>네트워크</span><span><i class="legend-dot usb-color"></i>USB / KVM</span>${srv?'':'<span><i class="legend-dot video-color"></i>영상</span>'}</div><div class="drag-note">드래그로 회전 · 스크롤로 확대</div></div><div class="system-instruction" aria-live="polite"><div class="overline" id="system-step-tag"></div><h3 id="system-step-title"></h3><p id="system-step-body"></p></div><div class="system-transport"><button class="secondary-button" id="system-prev">${icon('arrow-left')} 이전 설명</button><span class="stage-counter" id="system-counter"></span><button class="primary-button" id="system-next"></button></div></div></div><div class="system-note" id="system-note" role="status">${srv?'먼저 랙에 서버를 장착하세요. 단계별로 진행하면 Linux 설치 화면까지 안내합니다.':'다음 버튼으로 연결하거나, 아래 연결 패널에서 케이블을 직접 연결·분리할 수 있어요.'}</div><div class="ports-panel"><div class="panel-heading"><div><div class="overline">CONNECT / DISCONNECT</div><h3>연결 상태를 직접 바꿔보세요</h3></div><span>버튼을 누르면 연결 ↔ 분리</span></div><div class="ports-grid" id="ports-grid"></div><div class="port-hint" id="port-hint">${srv?'전원과 데이터는 별도 경로입니다. 연결된 장비를 클릭하면 역할을 설명해 드려요.':'모니터는 전원 + HDMI, 키보드·마우스는 USB, 통신은 LAN이 필요합니다.'}</div></div><div class="system-bottom ${srv?'server-workspace':''}">${srv?terminalHTML:desktopHTML}<div class="panel-card"><div class="panel-heading"><div><div class="overline">FOLLOW THE SIGNAL</div><h3>${srv?'요청은 어떻게 도착할까요?':'눈에 보이지 않던 신호의 길'}</h3></div><span>실시간 연결 상태</span></div><div class="flow-panel"><div class="flow-path" id="flow-path"></div><div class="flow-caption" id="flow-caption"></div><div class="device-explanation" id="device-explanation"><strong>${srv?'한 대의 서버, 여러 연결':'장치를 클릭해 보세요'}</strong>${srv?'같은 LAN의 요청은 스위치를 거칩니다. 다른 네트워크로 나갈 때는 게이트웨이가 필요해요.':'3D 모델의 장치 이름이나 장치를 클릭하면 어떤 일을 하는지 알려드려요.'}</div><div class="event-log" id="event-log"></div></div>${srv?`<div class="server-web"><div class="address-bar"><span>http://office.example</span><span>마지막 요청 결과</span></div><div class="web-response offline" id="web-response"><strong>아직 응답이 없어요.</strong><p>Linux와 nginx를 준비한 뒤 요청을 보내세요.</p></div></div><div class="server-extra"><button class="secondary-button" id="server-request">HTTP 요청</button><button class="secondary-button" id="server-ip-request">IP로 요청</button><button class="secondary-button" id="server-power">서버 전원</button></div>`:''}</div></div>${srv?`<div class="ports-panel"><div class="panel-heading"><div><div class="overline">BREAK IT. UNDERSTAND IT.</div><h3>장애를 만들고 원인을 찾아보세요</h3></div><span>버튼을 다시 누르면 복구</span></div><div class="server-summary" id="server-summary"></div><div class="fault-buttons"><button data-fault="psuA">PSU A 분리</button><button data-fault="nic">서버 LAN 분리</button><button data-fault="dns">DNS 오류 만들기</button><button data-fault="mains">시설 정전 · UPS 테스트</button></div><div class="port-hint">LAN 장애 때는 로컬 콘솔로 복구해 보세요. DNS만 고장 나면 도메인 요청은 실패하지만 IP 요청은 동작합니다. 같은 PDU에 연결된 두 PSU는 독립 전원 경로를 뜻하지 않아요.</div></div><div class="systems-sources"><span><strong>실습 범위</strong> · 소규모 사무실의 단일 LAN·단일 서버를 단순화했습니다. 실제 운영에는 접근 정책, 패치, 모니터링, 백업 복구 시험, 전력·냉각 설계 등이 추가로 필요합니다. 설치 화면은 공식 설치기의 개념을 재구성했으며 실제 설치기를 그대로 실행하지 않습니다.</span><span><a href="https://canonical-subiquity.readthedocs-hosted.com/en/latest/tutorial/screen-by-screen.html" target="_blank" rel="noopener">Ubuntu 설치 가이드 ↗</a><br><a href="https://ubuntu.com/server/docs/how-to/security/openssh-server/" target="_blank" rel="noopener">OpenSSH 문서 ↗</a></span></div>`:'<div class="systems-sources"><span><strong>연결과 분리는 다르게 작동해요.</strong> USB 입력은 연결 즉시 사용할 수 있지만, PC 전원이 끊기면 다시 켜야 합니다. 모니터를 분리해도 PC의 계산은 계속됩니다. 이 실습의 라우터와 멀티탭 전원은 항상 공급됩니다.</span></div>'}`;
 $('#system-next').addEventListener('click',runStep);$('#system-prev').addEventListener('click',()=>{state().step=Math.max(0,state().step-1);refresh();});$('#system-reset').addEventListener('click',()=>{if(srv){clearInterval(installTimer);server=createServer();history.length=0;}else desktop=createDesktop();scene?.dispose();frame();});
 $('#systems-steps').addEventListener('click',e=>{const b=e.target.closest('[data-sysstep]');if(b&&!b.disabled){state().step=Number(b.dataset.sysstep);refresh();}});
 $('#ports-grid').addEventListener('click',e=>{const b=e.target.closest('[data-connection]');if(!b)return;const id=b.dataset.connection,c=(srv?serverConnections:desktopConnections).find(c=>c.id===id);toggleConnection(course,state(),id);note(`${c.label} ${state().connections[id]?'연결':'분리'} · ${c.detail}`);refresh();});
 $('#system-camera').addEventListener('click',()=>scene?.reset());$('#system-rear').addEventListener('click',()=>scene?.rear());$('#system-fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#system-stage').requestFullscreen();}catch{note('이 브라우저에서는 전체 화면을 사용할 수 없어요.',true);}});
 if(srv){$('#terminal-form').addEventListener('submit',e=>{e.preventDefault();execute($('#terminal-input').value);$('#terminal-input').value='';});document.querySelectorAll('[data-command]').forEach(b=>b.addEventListener('click',()=>execute(b.dataset.command)));document.querySelectorAll('[data-session]').forEach(b=>b.addEventListener('click',()=>{server.session=b.dataset.session;refresh();}));$('#server-request').addEventListener('click',()=>httpRequest(false));$('#server-ip-request').addEventListener('click',()=>httpRequest(true));$('#server-power').addEventListener('click',()=>{if(server.on){server.on=false;server.booted=false;reconcileServer(server);note('서버를 종료했습니다. 다시 누르면 전원을 켭니다.');}else{const r=serverAction(server,server.installed?'reboot':'boot');note(r.error||r,!!r.error);}refresh();});document.querySelectorAll('[data-fault]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.fault;if(id==='dns'){server.dnsFault=!server.dnsFault;note(server.dnsFault?'DNS 오류를 만들었습니다. 도메인 요청과 IP 요청을 비교하세요.':'DNS 응답을 복구했습니다.');event(server,server.dnsFault?'DNS 응답 실패':'DNS 정상');}else{toggleConnection('server',server,id);note(id==='mains'&&!server.connections.mains?'시설 전원이 끊겼습니다. UPS가 최대 15초 동안 랙 전원을 유지합니다.':`${id} ${server.connections[id]?'복구':'분리'}`);}refresh();}));renderHistory();}
 else{$('#io-form').addEventListener('submit',e=>{e.preventDefault();actDesk('input',$('#io-input').value||'HELLO, PC!');});$('#io-click').addEventListener('click',()=>actDesk('pointer'));$('#desk-ping').addEventListener('click',()=>actDesk('ping'));$('#desk-power').addEventListener('click',()=>{if(desktop.on){desktop.on=false;note('PC를 종료했습니다.');refresh();}else actDesk('boot');});}
 try{scene=createSystemsScene($('#system-canvas'),course,id=>{const d=details[id]||['장치','컴퓨터 시스템을 구성하는 요소입니다.'];$('#device-explanation').innerHTML=`<strong>${escape(d[0])}</strong>${escape(d[1])}`;});$('#system-canvas').dataset.ready='true';}catch(e){console.error(e);$('#system-canvas').innerHTML='<div class="system-load-error">3D를 표시할 수 없어요. WebGL 지원 브라우저에서 열어주세요.<br>아래 연결·설치 실습은 계속 사용할 수 있습니다.</div>';}
 setFlow(srv?'network':'input',false);refresh();
}
function note(message,error=false){if(!$('#system-note'))return;$('#system-note').textContent=message;$('#system-note').classList.toggle('error',error);}
function renderHistory(){const out=$('#terminal-output');if(!out)return;out.replaceChildren();if(!history.length){const line=document.createElement('div');line.textContent='PC LAB · simulated Linux console\nhelp로 명령을 확인하세요.\nLinux 설치 후 서버 명령을 사용할 수 있습니다.';out.appendChild(line);}for(const h of history){const el=document.createElement('div');el.className='terminal-line'+(h.command?' command':'');el.textContent=h.text;out.appendChild(el);}out.scrollTop=out.scrollHeight;}
function appendTerminal(command,output,origin=prompt()){if(command)history.push({command:true,text:`${origin} ${command}`});if(output)history.push({text:output});while(history.length>100)history.shift();renderHistory();}
function prompt(){return server.session==='client'?'operator@admin-pc:~$':`${server.user}@${server.host}:~$`;}
function execute(command){if(!command.trim())return;const before=prompt(),r=runCommand(server,command);if(r.clear)history.length=0;else{history.push({command:true,text:`${before} ${command}`},{text:r.output});while(history.length>100)history.shift();}renderHistory();if(r.flow)setFlow(r.flow);refresh();}
function refresh(){if(course==='pc')return;const s=state(),srv=course==='server',list=steps(),done=s.step>=list.length,current=list[Math.min(s.step,list.length-1)],q=srv?serverStatus(s):desktopStatus(s);$('#system-lab').dataset.course=course;$('#system-lab').dataset.step=String(s.step);$('#system-lab').dataset.completed=String(s.completed);$('#system-progress').textContent=`${s.completed} / ${list.length}`;$('#system-progress-fill').style.width=`${s.completed/list.length*100}%`;
 const stepList=$('#systems-steps'),scrollX=stepList.scrollLeft,scrollY=stepList.scrollTop;stepList.innerHTML=list.map((v,i)=>`<li><button data-sysstep="${i}" ${i>s.completed?'disabled':''} class="${i===s.step?'current':i<s.completed?'done':''}" ${i===s.step?'aria-current="step"':''}><span class="step-num">${i<s.completed?icon('check'):String(i+1).padStart(2,'0')}</span><span>${v.name}</span></button></li>`).join('');stepList.scrollLeft=scrollX;stepList.scrollTop=scrollY;if(stepList.dataset.currentStep!==String(s.step)){stepList.dataset.currentStep=String(s.step);const active=stepList.querySelector('.current');if(active){const a=active.getBoundingClientRect(),b=stepList.getBoundingClientRect();if(a.bottom>b.bottom)stepList.scrollTop+=a.bottom-b.bottom+8;if(a.top<b.top)stepList.scrollTop-=b.top-a.top+8;if(a.right>b.right)stepList.scrollLeft+=a.right-b.right+8;if(a.left<b.left)stepList.scrollLeft-=b.left-a.left+8;}}
 $('#system-step-tag').textContent=done?'YOUR LAB IS READY':current.tag;$('#system-step-title').textContent=done?(srv?'회사 서버가 준비됐습니다.':'나의 데스크 셋업, 완료!'):current.name;$('#system-step-body').textContent=done?(srv?'Linux 설치부터 SSH, 웹 서비스와 백업까지 완성했습니다. 아래 장애 실험과 터미널로 연결이 끊겼을 때 어떻게 진단하는지 연습해 보세요.':'입력과 출력, 전원과 통신의 경로를 모두 살펴봤어요. 케이블을 분리하고 다시 연결하며 어떤 기능이 영향을 받는지 확인해 보세요.'):current.body;$('#system-next').innerHTML=(done?'다시 설명 보기':s.installing?'설치 진행 중…':current.button)+icon('arrow-right');$('#system-next').disabled=!!s.installing;$('#system-prev').disabled=s.step===0;$('#system-counter').textContent=`${String(Math.min(s.step+1,list.length)).padStart(2,'0')} / ${list.length}`;
 const pills=srv?[[q.power,'전원'],[q.redundant,'PSU A+B'],[q.running,'Linux'],[q.lan,'IP 통신'],[q.ssh,'SSH'],[q.http,'HTTP']]:[[q.running,'PC 전원'],[q.screen,'화면 출력'],[q.keyboard,'키보드'],[q.mouse,'마우스'],[q.network,'네트워크']];$('#system-status').innerHTML=pills.map(([on,label])=>`<span class="state-pill ${on?'on':''}">${label} ${on?'ON':'OFF'}</span>`).join('')+(srv&&s.batteryActive?`<span class="state-pill warn">UPS ${s.battery}초</span>`:'')+'<span class="sys-simulation-badge">LIVE SIMULATION</span>';
 $('#ports-grid').innerHTML=(srv?serverConnections:desktopConnections).map(c=>`<button class="connection-card ${s.connections[c.id]?'connected':''}" data-connection="${c.id}" aria-pressed="${s.connections[c.id]}" aria-label="${c.label}"><span class="connection-symbol ${c.type}">${icon(c.type==='power'?'power':'cable')}</span><span class="connection-copy"><strong>${c.label}</strong><small>${c.from} → ${c.to}</small></span><span class="connection-state">${s.connections[c.id]?'연결됨 ↗':'연결 +'}</span></button>`).join('');
 $('#event-log').replaceChildren();s.events.forEach(t=>{const line=document.createElement('div');line.textContent='› '+t;$('#event-log').appendChild(line);});
 if(srv){$('#terminal-prompt').textContent=prompt();document.querySelectorAll('[data-session]').forEach(b=>b.classList.toggle('active',b.dataset.session===(s.session==='remote'?'client':s.session)));$('#server-summary').innerHTML=`<span>Ubuntu ${s.installed?'설치됨':'미설치'}</span><span>${escape(s.host)} · ${escape(s.network.ip)}/24</span><span>${s.storage==='mirror'?'RAID 1 · 480 GB':'단일 · 480 GB'}</span><span>백업 ${s.backup?'있음':'없음'}</span>`;document.querySelectorAll('[data-fault]').forEach(b=>{const id=b.dataset.fault,fault=id==='dns'?s.dnsFault:!s.connections[id];b.classList.toggle('active',fault);b.setAttribute('aria-pressed',String(fault));b.textContent=({psuA:fault?'PSU A 복구':'PSU A 분리',nic:fault?'서버 LAN 복구':'서버 LAN 분리',dns:fault?'DNS 복구':'DNS 오류 만들기',mains:fault?'시설 전원 복구':'시설 정전 · UPS 테스트'})[id];});$('#server-power').innerHTML=icon('power')+(s.on?'서버 종료':'서버 켜기');}
 else{$('#io-monitor').classList.toggle('off',!q.screen);$('#io-screen-caption').textContent=!s.connections.monitorPower?'MONITOR / POWER OFF':q.screen?'PC LAB / DESKTOP':'MONITOR / NO SIGNAL';$('#io-screen-output').textContent=!s.connections.monitorPower?'모니터 전원이 분리됐어요.':!q.screen?'화면 신호가 없어요.':s.text||'입력을 기다리고 있어요.';$('#io-click-output').textContent=q.screen?`CLICK ${s.clicks} · ${q.network?'192.168.10.20 / LAN 연결':'LAN 연결 없음'}`:'';$('#io-status').textContent=q.screen?'화면 출력 중':'출력 없음';$('#desk-power').innerHTML=icon('power')+(s.on?'PC 종료':'PC 켜기');}
 scene?.update(s);
}
function setFlow(type,animate=true){const srv=course==='server';const data=type==='http-ip'?[['관리 PC','스위치','서버 IP :80','200 OK'],'IP 주소를 직접 사용하므로 DNS 조회를 생략합니다. 같은 VLAN 안의 HTTP 요청은 라우터 업링크 없이 스위치를 통해 전달됩니다.']:type==='http-local'?[['서버 프로세스','loopback','nginx :80','200 OK'],'localhost 요청은 서버 내부에서 처리됩니다. 물리 LAN 케이블을 통과하지 않으므로 외부 접근 장애와 서비스를 구분해 진단할 수 있어요.']:type==='loopback'?[['프로세스','로컬 IP 스택','응답'],'자기 자신의 IP로 보내는 요청은 로컬에서 처리됩니다. 케이블을 통과하는 외부 통신을 검증하는 결과는 아닙니다.']:type==='ping-gateway'?[['관리 PC / 서버','스위치','게이트웨이','ICMP 응답'],'게이트웨이에 도달하려면 스위치와 라우터 사이의 업링크가 필요합니다. 같은 VLAN의 서버에 보내는 요청과 경로가 달라요.']:type==='ping-dns'?[['DNS 조회','관리 PC / 서버','스위치','서버 응답'],'이름을 IP로 찾은 다음 ICMP 요청을 보냅니다. 이름 조회와 실제 목적지 통신은 별도 단계예요.']:type==='input'?[['키보드','USB','CPU / OS','GPU','모니터'],'키 입력 → USB HID 보고서 → 프로그램 처리 → 화면 갱신. HDMI가 빠져 있어도 키 입력은 PC에서 처리될 수 있어요.']:type==='pointer'?[['마우스','USB','이벤트 처리','모니터'],'클릭 이벤트가 PC로 전달되고 화면이 갱신됩니다. 물리 입력과 영상 출력은 서로 다른 경로입니다.']:type==='ssh'?[['관리 PC','스위치','TCP 22','sshd'],'같은 VLAN 안에서 SSH로 암호화된 통신을 합니다. 로그인 후의 명령은 서버에서 실행되는 것으로 모의합니다.']:type==='http'?[['DNS 조회','관리 PC','스위치','nginx :80','200 OK'],'도메인을 IP로 찾은 뒤 HTTP 요청을 보냅니다. 같은 서브넷의 웹 요청 자체는 스위치를 통과하고, 라우터 업링크는 이 모델의 DNS 조회에 사용됩니다.']:srv?[['관리 PC','스위치','서버 NIC','응답'],'같은 LAN 통신과 게이트웨이 경로는 다릅니다. 업링크를 분리해도 같은 VLAN의 서버 IP에는 접근할 수 있어요.']:[['PC','라우터','ICMP 응답'],'PC가 게이트웨이 192.168.10.1로 ICMP Echo Request를 보내고 Echo Reply를 받습니다. 파란 점은 모의 패킷입니다.'];$('#flow-path').innerHTML=data[0].map((n,i)=>`${i?'<span class="flow-arrow">→</span>':''}<span class="flow-node" style="--delay:${i*.25}s">${n}</span>`).join('');$('#flow-caption').textContent=data[1];$('#flow-path').classList.toggle('active',animate);clearTimeout(flowTimer);if(animate){scene?.flow(type);flowTimer=setTimeout(()=>$('#flow-path')?.classList.remove('active'),6500);}}
function actDesk(action,value){const r=desktopAction(desktop,action,value);note(r.error||r,!!r.error);event(desktop,r.error||r);if(action==='ping')$('#desk-network').textContent=r.error?`연결 실패\n${r.error}`:`$ ping 192.168.10.1\n${r}\n요청 4 → 응답 4 (학습용 모의 결과)`;if(!r.error&&['input','pointer','ping'].includes(action))setFlow(action);refresh();return r;}
function runStep(){const s=state(),list=steps();if(s.step===list.length){s.step=0;refresh();return;}const item=list[s.step];let r;if(course==='desktop')r=actDesk(item.action);else{r=serverAction(s,item.action);if(r.installer){openInstaller();return;}note(r.error||r,!!r.error);event(s,r.error||r);if(!r.error&&['ssh','request','service','firewall','backup'].includes(item.action)){const examples=({ssh:[`ssh ${s.user}@${s.network.ip}`],service:['sudo apt update','sudo apt install nginx'],firewall:['sudo ufw allow OpenSSH','sudo ufw allow 80/tcp','sudo ufw enable'],backup:['backup'],request:['curl http://office.example']})[item.action];examples.forEach((command,i)=>appendTerminal(command,i===examples.length-1?r:'모의 실행 완료',item.action==='ssh'?'operator@admin-pc:~$':prompt()));if(item.action==='request')showWeb(r,false);if(['ssh','request'].includes(item.action))setFlow(item.action==='request'?'http':'ssh');}}
 if(!r.error){s.completed=Math.max(s.completed,s.step+1);s.step=Math.min(s.step+1,list.length);}refresh();}
function showWeb(text,error){const out=$('#web-response');if(!out)return;out.classList.toggle('offline',error);out.replaceChildren();const title=document.createElement('strong');title.textContent=error?'요청에 실패했어요.':server.webContent;const p=document.createElement('p');p.textContent=text;out.append(title,p);}
function httpRequest(byIP){const before=server.session;server.session='client';const r=runCommand(server,'curl http://'+(byIP?server.network.ip:'office.example'));server.session=before;const failed=!r.output.includes('200 OK');showWeb(r.output,failed);note(r.output,failed);event(server,failed?'HTTP 요청 실패':'HTTP 200 OK');if(!failed)setFlow(byIP?'http-ip':'http');refresh();}
function switchCourse(next){if(!['pc','desktop','server'].includes(next))return;const url=new URL(location.href);url.searchParams.set('lab',next);window.history.replaceState(null,'',url);document.dispatchEvent(new Event('coursechange'));scene?.dispose();scene=null;course=next;document.querySelectorAll('[data-course]').forEach(b=>{const active=b.dataset.course===course;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});$('#pc-lab').hidden=course!=='pc';$('#components').hidden=course!=='pc';$('#system-lab').hidden=course==='pc';$('#system-lab').setAttribute('aria-labelledby',`course-${course}`);if(course!=='pc')frame();}
document.querySelectorAll('[data-course]').forEach(b=>b.addEventListener('click',()=>switchCourse(b.dataset.course)));document.querySelector('nav a[href="#components"]').addEventListener('click',()=>switchCourse('pc'));

// Simplified installation wizard. Configuration never reaches a real OS or disk.
const dialog=document.createElement('dialog');dialog.id='linux-dialog';dialog.className='linux-dialog';dialog.setAttribute('aria-labelledby','installer-title');document.body.appendChild(dialog);
function openInstaller(){wizardPage=0;config={host:server.host,user:server.user,network:{...server.network},storage:server.storage,language:server.language,keyboard:server.keyboard,sshRequested:server.sshRequested};renderWizard();dialog.showModal();}
function collectConfig(){if(wizardPage===0){config.language=$('#install-language').value;config.keyboard=$('#install-keyboard').value;}if(wizardPage===1){config.network.mode=$('#install-network-mode').value;config.network.ip=config.network.mode==='dhcp'?'10.20.0.50':$('#install-ip').value.trim();config.network.gateway=$('#install-gateway').value.trim();config.network.dns=$('#install-dns').value.trim();}if(wizardPage===2)config.storage=dialog.querySelector('input[name="storage"]:checked').value;if(wizardPage===3){config.host=$('#install-host').value.trim();config.user=$('#install-user').value.trim();config.sshRequested=$('#install-ssh').checked;}}
function renderWizard(){const stageNames=['기본 설정','네트워크','스토리지','계정 · SSH','설치 확인'];let body='';
 if(wizardPage===0)body=`<h3>반가워요, Linux.</h3><p>Ubuntu Server 24.04 LTS를 기반으로 설치의 핵심 선택을 경험합니다. 실제 설치기 화면과 선택 항목은 버전에 따라 다를 수 있어요.</p><div class="install-form"><label>설치 언어<select id="install-language"><option ${config.language==='English'?'selected':''}>English</option><option ${config.language==='한국어'?'selected':''}>한국어</option></select></label><label>키보드 배열<select id="install-keyboard"><option value="us" ${config.keyboard==='us'?'selected':''}>English (US)</option><option value="kr" ${config.keyboard==='kr'?'selected':''}>Korean</option></select></label></div><div class="install-info">설치 미디어: Ubuntu Server 24.04 LTS · amd64<br>실습 장치: 32 GB RAM · SSD 480 GB × 2<br>선택값은 이 브라우저의 가상 서버에만 적용됩니다.</div>`;
 if(wizardPage===1)body=`<h3>서버의 주소를 정합니다.</h3><p>실습 LAN은 10.20.0.0/24입니다. DHCP는 주소를 자동 할당하고 고정 IP는 서버의 주소를 일정하게 유지합니다.</p><div class="install-form"><label class="full">주소 할당<select id="install-network-mode"><option value="static" ${config.network.mode==='static'?'selected':''}>고정 IP (Static)</option><option value="dhcp" ${config.network.mode==='dhcp'?'selected':''}>자동 할당 (DHCP · 10.20.0.50)</option></select></label><label>IPv4 /24<input id="install-ip" value="${escape(config.network.ip)}" ${config.network.mode==='dhcp'?'disabled':''}><small>.1은 라우터, .100은 관리 PC입니다.</small></label><label>게이트웨이<input id="install-gateway" value="${escape(config.network.gateway)}"></label><label class="full">DNS 서버<input id="install-dns" value="${escape(config.network.dns)}"><small>이 실습의 DNS 서비스는 10.20.0.1에 있습니다.</small></label></div>`;
 if(wizardPage===2)body=`<h3>운영체제가 머물 곳.</h3><p>이 실습의 SSD만 초기화합니다. 아래 RAID는 미러링 개념을 보여주는 단순화 모델이며, 실제 파티션과 UEFI 부트 이중화는 별도 구성합니다.</p><div class="storage-options"><label class="storage-choice"><input type="radio" name="storage" value="mirror" ${config.storage==='mirror'?'checked':''}> RAID 1 · 미러링<small>SSD 2개에 같은 데이터<br>가용 약 480 GB · 디스크 하나 장애 대비</small></label><label class="storage-choice"><input type="radio" name="storage" value="single" ${config.storage==='single'?'checked':''}> 단일 디스크<small>SSD 1개에 운영체제<br>가용 약 480 GB · 두 번째 디스크는 예비</small></label></div><div class="install-info">RAID는 백업이 아닙니다. 파일 삭제나 손상도 양쪽에 반영될 수 있어요. 별도 저장소에 백업하고 복원 가능 여부를 확인해야 합니다.</div>`;
 if(wizardPage===3)body=`<h3>관리자와 원격 접속.</h3><div class="install-form"><label>호스트 이름<input id="install-host" value="${escape(config.host)}" maxlength="31" autocomplete="off"></label><label>관리자 사용자 이름<input id="install-user" value="${escape(config.user)}" maxlength="31" autocomplete="off"></label><label class="full check-label"><input id="install-ssh" type="checkbox" ${config.sshRequested?'checked':''}> OpenSSH 설치 · 실습용 공개키 인증 활성화</label></div><div class="install-info">실습용 관리자 인증 정보를 자동 생성합니다. 실제 비밀번호나 개인키를 입력하지 않습니다.<br>실제 Ubuntu 설치에서는 관리자 암호를 설정하고 SSH 공개키를 신뢰할 수 있는 경로로 등록합니다. 여기서는 공개키 인증 성공을 모의합니다.</div>`;
 if(wizardPage===4)body=`<h3>이 설정으로 설치합니다.</h3><div class="install-summary"><div><small>운영체제</small>Ubuntu Server 24.04 LTS</div><div><small>언어 / 키보드</small>${escape(config.language)} / ${config.keyboard}</div><div><small>서버 / 사용자</small>${escape(config.host)} / ${escape(config.user)}</div><div><small>네트워크</small>${escape(config.network.ip)}/24 (${config.network.mode})</div><div><small>가상 스토리지</small>${config.storage==='mirror'?'RAID 1 · 480 GB':'단일 디스크 · 480 GB'}</div><div><small>SSH</small>${config.sshRequested?'설치 · 공개키 인증':'설치하지 않음'}</div></div><div class="install-info">실습용 가상 디스크에만 설치합니다. 실제 컴퓨터의 디스크·파일·설정은 변경되지 않습니다.</div>`;
 dialog.innerHTML=`<div class="installer-header"><div class="eyebrow">VIRTUAL INSTALLER / NO REAL DISK ACCESS</div><h2 id="installer-title">Ubuntu Server 설치 실습</h2><p>${wizardPage+1} / 5 · ${stageNames[wizardPage]}</p><button class="dialog-close icon-button" id="install-close" aria-label="설치 창 닫기">${icon('close')}</button></div><div class="install-step-tabs">${stageNames.map((_,i)=>`<span class="${i<=wizardPage?'active':''}"></span>`).join('')}</div><div class="installer-body">${body}</div><div class="installer-error" id="installer-error" role="alert"></div><div class="installer-footer"><button class="secondary-button" id="install-back" ${wizardPage===0?'disabled':''}>이전</button><button class="primary-button" id="install-next">${wizardPage===4?'가상 디스크에 설치':'다음'} ${icon('arrow-right')}</button></div>`;
 $('#install-close').addEventListener('click',()=>dialog.close());$('#install-back').addEventListener('click',()=>{collectConfig();wizardPage--;renderWizard();});$('#install-next').addEventListener('click',()=>{collectConfig();if(wizardPage===1&&config.network.mode==='dhcp'&&!(serverStatus(server).power&&server.connections.nic&&server.connections.uplink)){$('#installer-error').textContent='DHCP 응답이 없습니다. 설치 창을 닫고 서버 LAN과 라우터 업링크를 연결하세요.';return;}const err=wizardPage===1?validateConfig({...config,host:'office-web',user:'admin'}):wizardPage>=3?validateConfig(config):'';if(err){$('#installer-error').textContent=err;return;}if(wizardPage===4)startInstall();else{wizardPage++;renderWizard();}});if(wizardPage===1)$('#install-network-mode').addEventListener('change',e=>{$('#install-ip').disabled=e.target.value==='dhcp';if(e.target.value==='dhcp')$('#install-ip').value='10.20.0.50';});
}
function startInstall(){const q=serverStatus(server);if(!q.power||!server.on||!server.connections.console){$('#installer-error').textContent='전원과 KVM 연결을 복구한 뒤 다시 시작하세요.';return;}Object.assign(server,config,{network:{...config.network},installing:true,installed:false,nginx:false,nginxInstalled:false,ssh:false,firewall:false,allowSSH:false,allowHTTP:false});dialog.innerHTML=`<div class="installer-header"><div class="eyebrow">INSTALLING / SIMULATION</div><h2 id="installer-title">서버에 첫 숨을 불어넣는 중.</h2><p>가상 디스크를 준비하고 Linux를 설치합니다.</p></div><div class="installer-body"><div class="install-progress"><div id="install-progress-bar"></div></div><div class="install-log" id="install-log" role="status"></div></div><div class="installer-footer"><span class="terminal-sim-note">실제 디스크 접근 없음</span><button class="secondary-button" id="install-cancel">실습 설치 취소</button></div>`;let phase=0;const phases=['가상 디스크 / EFI · root 구성','Linux 기본 시스템 복사','호스트 · 사용자 · 네트워크 설정','선택한 SSH 설정 적용','설치 완료 · 재부팅 준비'];$('#install-cancel').addEventListener('click',()=>{clearInterval(installTimer);server.installing=false;server.installed=false;dialog.close();note('가상 설치를 취소했습니다. 설치 단계를 다시 실행할 수 있어요.');refresh();});refresh();clearInterval(installTimer);installTimer=setInterval(()=>{if(!server.installing||!serverStatus(server).power){clearInterval(installTimer);server.installing=false;server.installed=false;dialog.innerHTML='<div class="installer-body"><h3>설치가 중단됐어요.</h3><p>전원 연결을 복구한 뒤 다시 설치하세요.</p><button class="primary-button" id="install-interrupted-close">닫기</button></div>';$('#install-interrupted-close').addEventListener('click',()=>dialog.close());refresh();return;}phase++;$('#install-progress-bar').style.width=`${phase*20}%`;$('#install-log').textContent=phases.slice(0,phase).map(p=>'✓ '+p).join('\n');if(phase===5){clearInterval(installTimer);server.installing=false;server.installed=true;server.needsReboot=true;server.ssh=server.sshRequested;server.completed=Math.max(server.completed,8);server.step=8;event(server,'Ubuntu Server 가상 설치 완료');dialog.innerHTML=`<div class="installer-header"><div class="eyebrow">INSTALLATION COMPLETE</div><h2 id="installer-title">Linux 설치 완료!</h2><p>이제 USB를 제거하고 재부팅합니다.</p></div><div class="installer-body"><div class="install-done">${icon('check')}</div><h3>${escape(server.host)}가 준비됐어요.</h3><p>${escape(server.network.ip)}/24 · ${server.storage==='mirror'?'RAID 1':'단일 디스크'} · SSH ${server.ssh?'설치됨':'미설치'}</p><div class="install-info">다음 단계에서 가상 USB를 제거하고 새 운영체제로 부팅하세요.</div><button class="primary-button" id="install-finish">실험실로 돌아가기 ${icon('arrow-right')}</button></div>`;$('#install-finish').addEventListener('click',()=>dialog.close());refresh();}},900);}
dialog.addEventListener('cancel',e=>{if(server.installing)e.preventDefault();});
setInterval(()=>{if(server.batteryActive&&!server.connections.mains&&server.battery>0){server.battery--;reconcileServer(server);if(course==='server')refresh();}},1000);
const initialCourse=new URLSearchParams(location.search).get('lab');switchCourse(['pc','server'].includes(initialCourse)?initialCourse:'desktop');
